        }
    }

    pub fn from_project_dirs() -> Self {
        Self::from_dirs(PROJECT_DIRS.cache_dir(), PROJECT_DIRS.config_dir())
    }

    pub fn with_interactive(mut self, interactive_output: bool) -> Self {
        self.interactive_output = interactive_output;
        self
    }

    pub fn cache_dir_display(&self) -> String {
        self.cache_dir.to_string_lossy().into_owned()
    }

    pub fn clear_cached_assets(&self) {
        self.remove_asset_file(self.cache_dir.join("themes.bin"), "theme set cache");
        self.remove_asset_file(self.cache_dir.join("syntaxes.bin"), "syntax set cache");
        self.remove_asset_file(self.cache_dir.join("metadata.yaml"), "metadata file");
    }

    fn remove_asset_file(&self, path: PathBuf, description: &str) {
        print!("Clearing {} ... ", description);
        match fs::remove_file(&path) {
            Err(err) if err.kind() == io::ErrorKind::NotFound => {
                println!("skipped (not present)");
            }
            Err(err) => {
                println!("could not remove the cache file {:?}: {}", &path, err);
            }
            Ok(_) => println!("okay"),
        }
    }

    pub fn assets_from_cache_or_binary(
        &self,
        use_custom_assets: bool,
    ) -> Result<HighlightingAssets> {
        Self::load_assets_from_dir(&self.cache_dir, use_custom_assets)
    }

    fn load_assets_from_dir(
        cache_dir: &Path,
        use_custom_assets: bool,
    ) -> Result<HighlightingAssets> {
        if let Some(metadata) = AssetsMetadata::load_from_folder(cache_dir)? {
            if !metadata.is_compatible_with(crate_version!()) {
                return Err(format!(
                    "The binary caches for the user-customized syntaxes and themes \
             in '{}' are not compatible with this version of bat ({}). To solve this, \
             either rebuild the cache (bat cache --build) or remove \
             the custom syntaxes/themes (bat cache --clear).\n\
             For more information, see:\n\n  \
             https://github.com/sharkdp/bat#adding-new-syntaxes--language-definitions",
                    cache_dir.to_string_lossy(),
                    crate_version!()
                )
                .into());
            }
        }

        let custom_assets = if use_custom_assets {
            HighlightingAssets::from_cache(cache_dir).ok()
        } else {
            None
        };
        Ok(custom_assets.unwrap_or_else(HighlightingAssets::from_binary))
    }

    pub fn config_dir_display(&self) -> String {
        self.config_dir.to_string_lossy().into_owned()
    }

