    let source_dir = matches
        .get_one::<String>("source")
        .map(Path::new)
        .unwrap_or_else(|| self.config_dir.as_path());
    let target_dir = matches
        .get_one::<String>("target")
        .map(Path::new)
        .unwrap_or_else(|| self.cache_dir.as_path());

    bat::assets::build(
        source_dir,
        !matches.get_flag("blank"),
        matches.get_flag("acknowledgements"),
        target_dir,
        clap::crate_version!(),
    )
}

pub fn run_cache_subcommand(&self, matches: &ArgMatches) -> Result<()> {
    if matches.get_flag("build") {
        #[cfg(feature = "build-assets")]
        self.build_assets(matches)?;
        #[cfg(not(feature = "build-assets"))]
        println!("bat has been built without the 'build-assets' feature. The 'cache --build' option is not available.");
    } else if matches.get_flag("clear") {
        self.remove_asset_file(self.cache_dir.join("themes.bin"), "theme set cache");
        self.remove_asset_file(self.cache_dir.join("syntaxes.bin"), "syntax set cache");
        self.remove_asset_file(self.cache_dir.join("metadata.yaml"), "metadata file");
    }
    Ok(())
}

